// TypeScript port of server/tvre/indicators.py (Pine ta.* semantics). Values before warm-up are NaN.
// Kept numerically identical to the Python reference: web/test/indicators.test.ts checks both on a
// shared fixture generated by server/scripts/make_fixture.py.
export type Series = Float64Array;
export interface Bar { time: number; open: number; high: number; low: number; close: number; volume: number }

const nan = (n: number) => new Float64Array(n).fill(NaN);

export function sma(src: ArrayLike<number>, length: number): Series {
  const n = src.length, out = nan(n);
  if (length <= 0 || n < length) return out;
  let sum = 0, nans = 0;
  for (let i = 0; i < n; i++) {
    const x = src[i];
    if (Number.isNaN(x)) nans++; else sum += x;
    if (i >= length) { const y = src[i - length]; if (Number.isNaN(y)) nans--; else sum -= y; }
    if (i >= length - 1 && nans === 0) out[i] = sum / length;
  }
  return out;
}

function seededMa(src: ArrayLike<number>, length: number, alpha: number): Series {
  const n = src.length, out = nan(n);
  let start = -1;
  for (let i = 0; i < n; i++) if (!Number.isNaN(src[i])) { start = i; break; }
  if (start < 0 || n - start < length) return out;
  const seedEnd = start + length - 1;
  let prev = 0;
  for (let i = start; i <= seedEnd; i++) { if (Number.isNaN(src[i])) return out; prev += src[i]; }
  prev /= length;
  out[seedEnd] = prev;
  for (let i = seedEnd + 1; i < n; i++) {
    const x = src[i];
    if (!Number.isNaN(x)) prev = alpha * x + (1 - alpha) * prev;
    out[i] = prev;
  }
  return out;
}

export const ema = (src: ArrayLike<number>, length: number) => seededMa(src, length, 2 / (length + 1));
export const rma = (src: ArrayLike<number>, length: number) => seededMa(src, length, 1 / length);

export function wma(src: ArrayLike<number>, length: number): Series {
  const n = src.length, out = nan(n), denom = (length * (length + 1)) / 2;
  for (let i = length - 1; i < n; i++) {
    let s = 0;
    for (let k = 0; k < length; k++) s += src[i - length + 1 + k] * (k + 1);
    out[i] = s / denom;
  }
  return out;
}

export function stdev(src: ArrayLike<number>, length: number): Series {
  const n = src.length, out = nan(n);
  for (let i = length - 1; i < n; i++) {
    let m = 0;
    for (let k = i - length + 1; k <= i; k++) m += src[k];
    m /= length;
    let v = 0;
    for (let k = i - length + 1; k <= i; k++) v += (src[k] - m) ** 2;
    out[i] = Math.sqrt(v / length);
  }
  return out;
}

const diff = (src: ArrayLike<number>) => { const o = nan(src.length); for (let i = 1; i < src.length; i++) o[i] = src[i] - src[i - 1]; return o; };
const map = (a: ArrayLike<number>, f: (x: number, i: number) => number) => { const o = new Float64Array(a.length); for (let i = 0; i < a.length; i++) o[i] = f(a[i], i); return o; };

export function rsi(src: ArrayLike<number>, length = 14): Series {
  const ch = diff(src);
  const up = rma(map(ch, x => (Number.isNaN(x) ? NaN : Math.max(x, 0))), length);
  const dn = rma(map(ch, x => (Number.isNaN(x) ? NaN : -Math.min(x, 0))), length);
  return map(up, (u, i) => {
    const d = dn[i];
    if (Number.isNaN(u) || Number.isNaN(d)) return NaN;
    if (d === 0) return 100;
    if (u === 0) return 0;
    return 100 - 100 / (1 + u / d);
  });
}

export function macd(src: ArrayLike<number>, fast = 12, slow = 26, signal = 9) {
  const f = ema(src, fast), s = ema(src, slow);
  const line = map(f, (x, i) => x - s[i]);
  const sig = ema(line, signal);
  return { macd: line, signal: sig, hist: map(line, (x, i) => x - sig[i]) };
}

export function bollinger(src: ArrayLike<number>, length = 20, mult = 2) {
  const basis = sma(src, length), dev = stdev(src, length);
  return { basis, upper: map(basis, (b, i) => b + mult * dev[i]), lower: map(basis, (b, i) => b - mult * dev[i]) };
}

export function trueRange(high: ArrayLike<number>, low: ArrayLike<number>, close: ArrayLike<number>): Series {
  return map(high, (h, i) => (i === 0 ? h - low[0]
    : Math.max(h - low[i], Math.abs(h - close[i - 1]), Math.abs(low[i] - close[i - 1]))));
}

export const atr = (h: ArrayLike<number>, l: ArrayLike<number>, c: ArrayLike<number>, length = 14) => rma(trueRange(h, l, c), length);

function rolling(src: ArrayLike<number>, length: number, f: (a: number, b: number) => number): Series {
  const out = nan(src.length);
  for (let i = length - 1; i < src.length; i++) {
    let acc = src[i - length + 1];
    for (let k = i - length + 2; k <= i; k++) acc = f(acc, src[k]);
    out[i] = acc;
  }
  return out;
}

export function stoch(close: ArrayLike<number>, high: ArrayLike<number>, low: ArrayLike<number>, kLength = 14, kSmooth = 1, dSmooth = 3) {
  const hh = rolling(high, kLength, Math.max), ll = rolling(low, kLength, Math.min);
  const raw = map(close, (c, i) => (100 * (c - ll[i])) / (hh[i] - ll[i]));
  const k = sma(raw, kSmooth);
  return { k, d: sma(k, dSmooth) };
}

export function obv(close: ArrayLike<number>, volume: ArrayLike<number>): Series {
  const out = new Float64Array(close.length);
  let acc = 0;
  for (let i = 0; i < close.length; i++) {
    if (i > 0) acc += Math.sign(close[i] - close[i - 1]) * volume[i];
    out[i] = acc;
  }
  return out;
}

export function vwap(high: ArrayLike<number>, low: ArrayLike<number>, close: ArrayLike<number>, volume: ArrayLike<number>, sessions: ArrayLike<number>): Series {
  const out = new Float64Array(close.length);
  let pv = 0, vv = 0;
  for (let i = 0; i < close.length; i++) {
    if (i === 0 || sessions[i] !== sessions[i - 1]) { pv = 0; vv = 0; }
    const tp = (high[i] + low[i] + close[i]) / 3;
    pv += tp * volume[i]; vv += volume[i];
    out[i] = vv ? pv / vv : tp;
  }
  return out;
}

// ------------------------------------------------------------------ registry (UI metadata)
export type Inputs = Record<string, number | string>;
export interface OutputStyle { key: string; color: string; kind?: 'line' | 'histogram'; title?: string }
export interface IndicatorDef {
  id: string; name: string; pane: 'overlay' | 'separate'; inputs: Inputs; outputs: OutputStyle[];
  levels?: number[]; compute(b: Columns, p: Inputs): Record<string, Series>;
}
export interface Columns { time: Float64Array; open: Float64Array; high: Float64Array; low: Float64Array; close: Float64Array; volume: Float64Array }

export function columns(bars: Bar[]): Columns {
  const pick = (k: keyof Bar) => Float64Array.from(bars, b => b[k]);
  return { time: pick('time'), open: pick('open'), high: pick('high'), low: pick('low'), close: pick('close'), volume: pick('volume') };
}
const src = (b: Columns, p: Inputs) => b[(p.source as keyof Columns) ?? 'close'] ?? b.close;
const num = (v: number | string) => Number(v);

export const INDICATORS: Record<string, IndicatorDef> = {
  SMA: { id: 'SMA', name: 'Moving Average Simple', pane: 'overlay', inputs: { length: 9, source: 'close' },
    outputs: [{ key: 'ma', color: '#2962FF' }], compute: (b, p) => ({ ma: sma(src(b, p), num(p.length)) }) },
  EMA: { id: 'EMA', name: 'Moving Average Exponential', pane: 'overlay', inputs: { length: 9, source: 'close' },
    outputs: [{ key: 'ma', color: '#FF6D00' }], compute: (b, p) => ({ ma: ema(src(b, p), num(p.length)) }) },
  WMA: { id: 'WMA', name: 'Moving Average Weighted', pane: 'overlay', inputs: { length: 9, source: 'close' },
    outputs: [{ key: 'ma', color: '#AB47BC' }], compute: (b, p) => ({ ma: wma(src(b, p), num(p.length)) }) },
  BB: { id: 'BB', name: 'Bollinger Bands', pane: 'overlay', inputs: { length: 20, mult: 2, source: 'close' },
    outputs: [{ key: 'basis', color: '#FF6D00' }, { key: 'upper', color: '#2962FF' }, { key: 'lower', color: '#2962FF' }],
    compute: (b, p) => bollinger(src(b, p), num(p.length), num(p.mult)) },
  VWAP: { id: 'VWAP', name: 'VWAP', pane: 'overlay', inputs: {}, outputs: [{ key: 'vwap', color: '#2962FF' }],
    compute: b => ({ vwap: vwap(b.high, b.low, b.close, b.volume, map(b.time, t => Math.floor(t / 86400))) }) },
  // TradingView's RSI also plots an "RSI-based MA" (SMA 14 of RSI) by default
  RSI: { id: 'RSI', name: 'Relative Strength Index', pane: 'separate', inputs: { length: 14, source: 'close', ma_length: 14 },
    outputs: [{ key: 'rsi', color: '#7E57C2' }, { key: 'rsi_ma', color: '#F7C11E' }], levels: [70, 50, 30],
    compute: (b, p) => { const r = rsi(src(b, p), num(p.length)); return { rsi: r, rsi_ma: sma(r, num(p.ma_length)) }; } },
  MACD: { id: 'MACD', name: 'MACD', pane: 'separate', inputs: { fast: 12, slow: 26, signal: 9, source: 'close' },
    outputs: [{ key: 'hist', color: '#26A69A', kind: 'histogram' }, { key: 'macd', color: '#2962FF' }, { key: 'signal', color: '#FF6D00' }],
    compute: (b, p) => macd(src(b, p), num(p.fast), num(p.slow), num(p.signal)) },
  ATR: { id: 'ATR', name: 'Average True Range', pane: 'separate', inputs: { length: 14 },
    outputs: [{ key: 'atr', color: '#B71C1C' }], compute: (b, p) => ({ atr: atr(b.high, b.low, b.close, num(p.length)) }) },
  STOCH: { id: 'STOCH', name: 'Stochastic', pane: 'separate', inputs: { k: 14, k_smooth: 3, d: 3 },   // TradingView default 14/3/3
    outputs: [{ key: 'k', color: '#2962FF' }, { key: 'd', color: '#FF6D00' }], levels: [80, 50, 20],
    compute: (b, p) => stoch(b.close, b.high, b.low, num(p.k), num(p.k_smooth), num(p.d)) },
  OBV: { id: 'OBV', name: 'On Balance Volume', pane: 'separate', inputs: {}, outputs: [{ key: 'obv', color: '#2962FF' }],
    compute: b => ({ obv: obv(b.close, b.volume) }) },
};

export function computeIndicator(id: string, bars: Columns, inputs: Inputs = {}): Record<string, Series> {
  const def = INDICATORS[id];
  return def.compute(bars, { ...def.inputs, ...inputs });
}
